import React from 'react';
import { NavLink, Link, useNavigate } from 'react-router-dom';
import {
  LayoutDashboard,
  Scan,
  LineChart,
  Database,
  HelpCircle,
  Info,
  Sliders,
  Sparkles,
  Layers,
  GraduationCap,
  Brain,
  FolderKanban,
  Target,
  MessageSquare,
  Cpu,
  TrendingUp,
  RotateCcw,
  ArrowRight,
} from 'lucide-react';
import { useLanguage } from '../../context/LanguageContext';
import { useUser } from '../../context/UserContext';

const Sidebar: React.FC = () => {
  const { t } = useLanguage();
  const { isStudent, setRole } = useUser();
  const navigate = useNavigate();

  const patientNavItems = [
    { to: '/', label: t('nav.home'), icon: LayoutDashboard, end: true },
    { to: '/tasks', label: 'Conditions & Tasks', icon: Layers },
    { to: '/scans', label: t('nav.scan_center'), icon: Scan },
    { to: '/evaluation', label: t('nav.evaluation'), icon: LineChart },
    { to: '/dataset', label: t('nav.dataset'), icon: Database },
    { to: '/how-it-works', label: t('nav.how_it_works'), icon: HelpCircle },
    { to: '/about', label: t('nav.about'), icon: Info },
    { to: '/settings', label: t('nav.settings'), icon: Sliders },
  ];

  const studentNavItems = [
    { to: '/student', label: 'Student Dashboard', icon: GraduationCap, end: true },
    { to: '/student/features', label: 'Learn MRI Features', icon: Layers },
    { to: '/student/journey', label: 'CNN Visual Journey', icon: Cpu },
    { to: '/student/tumors', label: 'Brain Tumor Classes', icon: Brain },
    { to: '/student/cases', label: 'Case Library & Practice', icon: FolderKanban },
    { to: '/student/quizzes', label: 'Topic Quizzes', icon: HelpCircle },
    { to: '/student/profile', label: 'Progress & Revision', icon: TrendingUp },
  ];

  const navItems = isStudent ? studentNavItems : patientNavItems;

  return (
    <aside className="w-64 shrink-0 hidden md:block border-r border-slate-800/80 bg-slate-950/50 min-h-[calc(100vh-4rem)] p-4 flex flex-col justify-between">
      <div className="space-y-4">
        {/* Role Header Banner */}
        <div className="px-3.5 py-2 rounded-xl bg-slate-900 border border-slate-800/80 flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <span
              className={`w-2 h-2 rounded-full ${
                isStudent ? 'bg-purple-400 animate-pulse' : 'bg-teal-400'
              }`}
            />
            <span className="text-xs font-bold text-slate-200">
              {isStudent ? 'Student Mode' : 'Workstation'}
            </span>
          </div>
          <button
            type="button"
            onClick={() => {
              if (isStudent) {
                setRole('patient');
                navigate('/tasks');
              } else {
                setRole('student');
                navigate('/student');
              }
            }}
            className="text-[10px] text-teal-400 hover:text-teal-300 font-mono underline"
          >
            Switch
          </button>
        </div>

        {/* Navigation Items */}
        <div className="space-y-1">
          {navItems.map((item) => {
            const Icon = item.icon;
            return (
              <NavLink
                key={item.to}
                to={item.to}
                end={item.end}
                className={({ isActive }) =>
                  `flex items-center space-x-3 px-3.5 py-2.5 rounded-xl text-sm font-medium transition-all ${
                    isActive
                      ? isStudent
                        ? 'bg-purple-500/10 text-purple-300 border border-purple-500/30 shadow-sm'
                        : 'bg-teal-500/10 text-teal-400 border border-teal-500/30 shadow-sm'
                      : 'text-slate-400 hover:text-slate-200 hover:bg-slate-900/60'
                  }`
                }
              >
                <Icon className="w-4 h-4 shrink-0" />
                <span className="truncate">{item.label}</span>
              </NavLink>
            );
          })}
        </div>
      </div>

      {/* Role Switch Callout Widget */}
      <div className="mt-8 p-3.5 rounded-xl bg-slate-900/70 border border-slate-800 text-xs space-y-2.5">
        <div className="flex items-center space-x-2 text-teal-400 font-semibold">
          {isStudent ? (
            <>
              <GraduationCap className="w-3.5 h-3.5" />
              <span>Medical Student Lab</span>
            </>
          ) : (
            <>
              <Sparkles className="w-3.5 h-3.5" />
              <span>Patient Workstation</span>
            </>
          )}
        </div>
        <p className="text-slate-400 leading-relaxed text-[11px]">
          {isStudent
            ? 'Practice on de-identified cases and study CNN visual feature extraction.'
            : 'Explore patient MRI scan upload and automated classification.'}
        </p>
        <button
          type="button"
          onClick={() => {
            if (isStudent) {
              setRole('patient');
              navigate('/tasks');
            } else {
              setRole('student');
              navigate('/student');
            }
          }}
          className="w-full py-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-[11px] font-bold text-slate-200 transition-colors flex items-center justify-center space-x-1"
        >
          <span>{isStudent ? 'Go to Patient Tasks' : 'Open Student Lab'}</span>
          <ArrowRight className="w-3 h-3" />
        </button>
      </div>
    </aside>
  );
};

export default Sidebar;

